CREATE TABLE "public"."skills" (
  "id"      bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "heading" text,
  "content" text   DEFAULT '''{}''::text[]'::text,
  CONSTRAINT "skills_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."skills"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public can read skills" ON "public"."skills"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

REVOKE ALL ON SEQUENCE "public"."skills_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."skills_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."skills_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."skills_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."skills_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."skills_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."skills_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."skills_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."skills" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."skills" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."skills" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."skills" TO "service_role";

